bsl_m=; if [ -r /usr/lib/breadstick/bsl-os.sh ] && . /usr/lib/breadstick/bsl-os.sh && command -v bsl_pkg_mark >/dev/null 2>&1 && command -v bsl_pkg_also >/dev/null 2>&1 && bsl_pkg_mark refresh; then bsl_m=1; fi
( [ -z "$bsl_m" ] || bsl_pkg_also $$
R=breadstick; grep -qsx '\[breadstick-test\]' /etc/yum.repos.d/*.repo /etc/distro.repos.d/*.repo /usr/share/dnf5/repos.d/*.repo && R=breadstick-test; L=$(mktemp); { r=0; LC_ALL=C dnf -y makecache --refresh --repo="$R" --setopt="$R".skip_if_unavailable=False 2>&1 || r=$?; echo; echo "refresh exit $r"; } | tee "$L"; fresh=0; grep -qx 'refresh exit 0' "$L" && fresh=1; rm -f "$L"; P=$(rpm -qa --qf '%{NAME}\n' 'breadstick-*' 2>/dev/null | sort -u | tr '\n' ' '); if [ -n "$P" ]; then dnf -y upgrade --setopt=install_weak_deps=False --setopt=skip_if_unavailable=True '--setopt=*.skip_if_unavailable=True' --skip-unavailable --from-repo="$R" $P || exit $?; fi; rpm -q breadstick-desktop >/dev/null 2>&1 || dnf -y install --setopt=install_weak_deps=False --setopt=skip_if_unavailable=True '--setopt=*.skip_if_unavailable=True' breadstick-desktop || exit $?; { rpm -q breadstick-print >/dev/null 2>&1 || dnf -y install --setopt=install_weak_deps=False --setopt=skip_if_unavailable=True '--setopt=*.skip_if_unavailable=True' breadstick-print >/dev/null 2>&1 || true; }; [ $fresh = 1 ] || { echo "Breadstick's package index did not refresh: the daily check is not marked done"; exit 75; }
); bsl_rc=$?; [ -z "$bsl_m" ] || bsl_pkg_unmark $bsl_rc; exit $bsl_rc
